/* * Copyright (c) 2026 Yuzuki Tsuru * * SPDX-License-Identifier: Apache-2.0 */ /* * Host build of the same decoder: decodes an ADTS file and prints the CRC-32 of the PCM, to * compare with the board. usage: host_decode FILE.aac DESIRED_CHANNELS OUT.pcm */ #include <stdint.h> #include <stdio.h> #include <stdlib.h> #include <pvmp4audiodecoder_api.h> static uint8_t in[256 * 1024]; static int16_t pcm[2048 * 2]; static uint32_t crc32_update(uint32_t crc, const void *data, size_t len) { const uint8_t *p = data; crc = ~crc; while (len--) { crc ^= *p++; for (int k = 0; k < 8; k++) { crc = (crc >> 1) ^ (0xedb88320U & -(crc & 1)); } } return ~crc; } int main(int argc, char **argv) { tPVMP4AudioDecoderExternal ext = {0}; uint32_t crc = 0; int frames = 0; size_t n; void *mem; FILE *f; FILE *out; int desired; if (argc != 4) { fprintf(stderr, "usage: %s FILE.aac DESIRED_CHANNELS OUT.pcm
", argv[0]); return 1; } f = fopen(argv[1], "rb"); out = fopen(argv[3], "wb"); if (f == NULL || out == NULL) { return 1; } n = fread(in, 1, sizeof(in), f); desired = atoi(argv[2]); mem = malloc(PVMP4AudioDecoderGetMemRequirements()); ext.desiredChannels = desired; ext.outputFormat = OUTPUTFORMAT_16PCM_INTERLEAVED; ext.aacPlusEnabled = false; PVMP4AudioDecoderInitLibrary(&ext, mem); ext.pInputBuffer = in; ext.inputBufferCurrentLength = n; while (ext.inputBufferUsedLength + 7 < (int)n) { int ret; ext.pOutputBuffer = pcm; ext.pOutputBuffer_plus = pcm + 2048; ret = PVMP4AudioDecodeFrame(&ext, mem); if (ret != MP4AUDEC_SUCCESS) { printf("error %d at frame %d
", ret, frames); break; } crc = crc32_update(crc, pcm, ext.frameLength * desired * sizeof(int16_t)); fwrite(pcm, sizeof(int16_t), ext.frameLength * desired, out); frames++; } printf("%d frames, %d Hz, CRC-32 %08x
", frames, (int)ext.samplingRate, crc); fclose(out); free(mem); return 0; }

/* * A USB host on the EHCI/OHCI controller of the YuzukiNeko, built on CherryUSB. The CherryUSB side is * in usb_host.c. The board has no switch for the 5 V of the USB port (see the devicetree), so a * device on the port has to be powered from outside; with none connected the demo only shows the * start of the stack. */ #include <zephyr/kernel.h> #include <zephyr/sys/printk.h> /* the register base of the EHCI controller, from the glue code of the board */ extern uintptr_t usb_sunxi_ehci_base(void); struct usbh_hubport; extern int usb_host_start(uintptr_t reg_base); extern int usb_host_stop(void); extern void usb_host_lsusb(void); extern struct usbh_hubport *usb_host_hubport(uint8_t port); extern void usb_host_report_port(uint8_t port); extern void usb_host_exercise(struct usbh_hubport *hport); extern bool usb_host_connected(struct usbh_hubport *hport); int main(void) { int ret = usb_host_start(usb_sunxi_ehci_base()); printk("usbh_initialize: %d
", ret); /* look at the root port for 10 seconds */ for (int i = 0; i < 10; i++) { struct usbh_hubport *hport = usb_host_hubport(1); if (hport != NULL && usb_host_connected(hport)) { usb_host_report_port(1); usb_host_exercise(hport); break; } k_msleep(1000); } usb_host_report_port(1); usb_host_lsusb(); ret = usb_host_stop(); printk("usbh_deinitialize: %d
", ret); printk("cherryusb_host_api done
"); return 0; }

/* * A USB CDC ACM (virtual serial port) device on the OTG controller of the YuzukiNeko, built on CherryUSB. * Everything the host sends to the port is sent back (cdc_echo.c); this file starts it and reports the * byte counts on the console. */ #include <zephyr/kernel.h> #include <zephyr/sys/printk.h> /* the register base of the OTG controller, from the glue code of the board */ extern uintptr_t usb_sunxi_otg_base(void); extern void cdc_echo_init(uintptr_t reg_base); extern uint32_t cdc_echo_rx_bytes(void); extern uint32_t cdc_echo_tx_bytes(void); extern uint32_t cdc_echo_transfers(void); int main(void) { cdc_echo_init(usb_sunxi_otg_base()); printk("usb_api started
"); /* report once a second while there is traffic; stop after the host has gone quiet */ uint32_t last = 0; int quiet = 0; while (quiet < 5) { k_msleep(1000); if (cdc_echo_rx_bytes() != last) { last = cdc_echo_rx_bytes(); printk("[echo] received %u bytes in %u transfer(s), sent back %u bytes
", last, cdc_echo_transfers(), cdc_echo_tx_bytes()); quiet = 0; } else if (last != 0) { quiet++; } } printk("usb_api done
"); return 0; }
